        <ErfolgsAnsicht titel="Anfrage eingegangen" text={erfolgText} dunkel={dunkel}>
          {ergebnis?.id && (
            <p className={cn("mt-3 text-[13.5px]", dunkel ? "text-white/75" : "text-ink-600")}>
